#!/usr/bin/env python3
"""Convert PEM CA certificates into a BearSSL trust-anchor C header.

Usage: python3 make_anchors.py [certs/foo.pem ...] > ../src/tls_anchors.h
With no arguments it converts every PEM in the certs/ directory next
to this script (sorted by filename) -- that is the reproducible
one-command regeneration used for the shipped header.

For each certificate it emits the DER-encoded subject Name and the
subject public key in br_x509_trust_anchor form (RSA modulus/exponent,
or EC curve id + uncompressed point). Pure stdlib DER walking; the
output is data only -- adding a root later means re-running this on a
new PEM, no code changes.
"""
import base64
import re
import sys


def read_tlv(buf, off):
    """Return (tag, header_len, value_len, value_off) for the TLV at off."""
    tag = buf[off]
    if tag & 0x1F == 0x1F:
        raise ValueError("multi-byte tags unsupported")
    lb = buf[off + 1]
    if lb & 0x80:
        n = lb & 0x7F
        ln = int.from_bytes(buf[off + 2:off + 2 + n], "big")
        hdr = 2 + n
    else:
        ln = lb
        hdr = 2
    return tag, hdr, ln, off + hdr


def children(buf, off):
    """Yield (start, total_len) for each child TLV of a constructed TLV."""
    tag, hdr, ln, voff = read_tlv(buf, off)
    end = voff + ln
    p = voff
    while p < end:
        t2, h2, l2, _ = read_tlv(buf, p)
        yield p, h2 + l2
        p += h2 + l2


def oid_str(b):
    out = [str(b[0] // 40), str(b[0] % 40)]
    v = 0
    for x in b[1:]:
        v = (v << 7) | (x & 0x7F)
        if not (x & 0x80):
            out.append(str(v))
            v = 0
    return ".".join(out)


EC_CURVES = {
    "1.2.840.10045.3.1.7": ("BR_EC_secp256r1", 23),
    "1.3.132.0.34": ("BR_EC_secp384r1", 24),
    "1.3.132.0.35": ("BR_EC_secp521r1", 25),
}


def parse_cert(der):
    cert_children = list(children(der, 0))          # Certificate SEQ
    tbs = cert_children[0][0]
    fields = list(children(der, tbs))               # tbsCertificate fields
    idx = 0
    if der[fields[0][0]] == 0xA0:                   # [0] version
        idx = 1
    subject_off = fields[idx + 4][0]                # after serial, sig, issuer, validity
    spki_off = fields[idx + 5][0]
    _, _, _, svo = read_tlv(der, subject_off)
    subj_len = (svo - subject_off) + read_tlv(der, subject_off)[2]
    subject = der[subject_off:subject_off + subj_len]

    spki = list(children(der, spki_off))
    alg = list(children(der, spki[0][0]))
    _, ah, al, avo = read_tlv(der, alg[0][0])
    alg_oid = oid_str(der[avo:avo + al])
    _, bh, bl, bvo = read_tlv(der, spki[1][0])      # BIT STRING
    assert der[bvo] == 0                          # no unused bits
    pub = der[bvo + 1:bvo + bl]
    if alg_oid == "1.2.840.113549.1.1.1":           # RSA
        ints = list(children(pub, 0))
        vals = []
        for (ioff, _l) in ints[:2]:
            _, ih, il, ivo = read_tlv(pub, ioff)
            v = pub[ivo:ivo + il]
            while len(v) > 1 and v[0] == 0:
                v = v[1:]
            vals.append(v)
        return subject, ("RSA", vals[0], vals[1])
    if alg_oid == "1.2.840.10045.2.1":              # EC
        _, ph, pl, pvo = read_tlv(der, alg[1][0])
        curve_oid = oid_str(der[pvo:pvo + pl])
        name, cid = EC_CURVES[curve_oid]
        return subject, ("EC", name, cid, pub)
    raise ValueError(f"unsupported key algorithm {alg_oid}")


def cbytes(name, data):
    lines = [f"static const unsigned char {name}[] = {{"]
    for i in range(0, len(data), 12):
        chunk = ", ".join(f"0x{x:02X}" for x in data[i:i + 12])
        lines.append("\t" + chunk + ",")
    lines.append("};")
    return "\n".join(lines)


def pem_to_der(path):
    txt = open(path).read()
    m = re.search(r"-----BEGIN CERTIFICATE-----(.*?)-----END CERTIFICATE-----",
                  txt, re.S)
    return base64.b64decode(re.sub(r"\s+", "", m.group(1)))


def main():
    paths = sys.argv[1:]
    if not paths:
        import glob
        import os
        here = os.path.dirname(os.path.abspath(__file__))
        paths = sorted(glob.glob(os.path.join(here, "certs", "*.pem")))
    out = []
    out.append("/* GENERATED by third_party/make_anchors.py -- do not edit.")
    out.append(" * Trust anchors for BearSSL br_x509_minimal, converted from")
    out.append(" * the PEM certificates in third_party/certs/. */")
    out.append("#ifndef TLS_ANCHORS_H")
    out.append("#define TLS_ANCHORS_H")
    out.append("")
    anchors = []
    for i, path in enumerate(paths):
        label = path.split("/")[-1].replace(".pem", "").replace("-", "_")
        der = pem_to_der(path)
        subject, key = parse_cert(der)
        pfx = f"ta_{i}_{label}"
        out.append(f"/* certs/{label.replace('_', '-')}.pem */")
        out.append(cbytes(pfx + "_dn", subject))
        if key[0] == "RSA":
            out.append(cbytes(pfx + "_n", key[1]))
            out.append(cbytes(pfx + "_e", key[2]))
            pkey = (f"{{ BR_KEYTYPE_RSA, {{ .rsa = {{ (unsigned char *){pfx}_n,"
                    f" sizeof {pfx}_n, (unsigned char *){pfx}_e, sizeof {pfx}_e }} }} }}")
        else:
            out.append(cbytes(pfx + "_q", key[3]))
            pkey = (f"{{ BR_KEYTYPE_EC, {{ .ec = {{ {key[1]},"
                    f" (unsigned char *){pfx}_q, sizeof {pfx}_q }} }} }}")
        anchors.append(
            f"\t{{ {{ (unsigned char *){pfx}_dn, sizeof {pfx}_dn }},"
            f" BR_X509_TA_CA, {pkey} }}")
        out.append("")
    out.append("static const br_x509_trust_anchor tls_trust_anchors[] = {")
    out.append(",\n".join(anchors))
    out.append("};")
    out.append("")
    out.append("#define TLS_TRUST_ANCHORS_NUM \\")
    out.append("\t(sizeof tls_trust_anchors / sizeof tls_trust_anchors[0])")
    out.append("")
    out.append("#endif")
    print("\n".join(out))


if __name__ == "__main__":
    main()
